-- Add ref_number column to website_transactions to store human-readable
-- payment reference from Payment Service (e.g., "INV-BAGDJADEV-PRODUCT-43A57B5A")
-- This is the payment_requests.external_id generated by Payment Service

ALTER TABLE website_transactions
ADD COLUMN IF NOT EXISTS ref_number VARCHAR(100) NULL;

-- Index for fast lookup by invoice/ref number
CREATE INDEX IF NOT EXISTS idx_website_transactions_ref_number
  ON website_transactions(ref_number);

-- Comment for documentation
COMMENT ON COLUMN website_transactions.ref_number IS 'Human-readable payment reference from Payment Service (payment_requests.external_id), e.g., INV-BAGDJADEV-PRODUCT-43A57B5A';